class Solution {
public:
    bool sumOfNumberAndReverse(int num) {
        for (int x = num / 2; x <= num; x++) {
            int rev = 0, temp = x;
            while (temp > 0) {
                rev = rev * 10 + (temp % 10);
                temp /= 10;
            }
            if (x + rev == num) return true;
        }
        return false;
    }
};

class Solution {
    public boolean sumOfNumberAndReverse(int num) {
        for (int x = num / 2; x <= num; x++) {
            int rev = 0, temp = x;
            while (temp > 0) {
                rev = rev * 10 + (temp % 10);
                temp /= 10;
            }
            if (x + rev == num) return true;
        }
        return false;
    }
}

var sumOfNumberAndReverse = function(num) {
    for (let x = Math.floor(num / 2); x <= num; x++) {
        let rev = 0, temp = x;
        while (temp > 0) {
            rev = rev * 10 + (temp % 10);
            temp = Math.floor(temp / 10);
        }
        if (x + rev === num) return true;
    }
    return false;
};
